#include "../PhiMod/Core/PMRPECore.hpp"
#include <iostream>
#include <cassert>
using namespace phimod::rpe;
int main(){int checks=0;for(int e=1;e<=29;++e)for(int i=0;i<=100;++i){double x=ease(e,i/100.);assert(std::isfinite(x));++checks;}for(int e=1;e<=29;++e){assert(std::abs(ease(e,0))<.00001);assert(std::abs(ease(e,1)-1)<.00001);checks+=2;}Tempo t;t.beats={0,4};t.times={0,2};t.bpms={120,60};assert(t.seconds(0)==0&&t.seconds(4)==2&&t.seconds(6)==4);t.factor=.5;assert(t.seconds(6)==2);Event e;e.s=0;e.e=2;e.a=10;e.b=20;assert(e.value(1)==15);e.bezier=true;e.points={0,0,1,1};assert(std::abs(e.value(1)-15)<.001);std::vector<Line>lines(2);Track x;x.events.push_back({0,10,100,100});lines[0].layers[0].push_back(x);lines[1].parent=0;std::vector<bool>seen(2);assert(pose(lines,1,1,seen)[0]==100);lines[0].parent=1;bool rejected=false;try{pose(lines,1,1,seen);}catch(const std::invalid_argument&){rejected=true;}assert(rejected);std::vector<Linear>out;auto fn=[](double v){return std::array<double,2>{v*v,v};};subdivide(out,fn,0,1,fn(0),fn(1),.0003);assert(out.size()>8);for(const auto&r:out){double s=r[0]/64,finish=r[1]/64,m=(s+finish)/2;assert(std::abs(m*m-(r[2]+r[3])/2)<=.0003);checks++;}std::cout<<"PASS RPE core "<<checks<<" timing/easing/parent/subdivision checks\n";}
